import{_ as l,o as i,c as t,a6 as r}from"./chunks/framework.CGCCzANv.js";const e="/Art_web_public/assets/image.MtjLXkYZ.png",o="/Art_web_public/assets/image-1.Hc1AiIxP.png",g=JSON.parse('{"title":"游戏音乐创作: 从零开始为游戏制作音乐","description":"","frontmatter":{"readingTime":"7 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/从零开始为游戏制作音乐/从零开始为游戏制作音乐.md","filePath":"游戏引擎/游戏设计/从零开始为游戏制作音乐/从零开始为游戏制作音乐.md"}'),h={name:"游戏引擎/游戏设计/从零开始为游戏制作音乐/从零开始为游戏制作音乐.md"};function n(s,a,d,p,u,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="游戏音乐创作-从零开始为游戏制作音乐" tabindex="-1">游戏音乐创作: 从零开始为游戏制作音乐 <a class="header-anchor" href="#游戏音乐创作-从零开始为游戏制作音乐" aria-label="Permalink to &quot;游戏音乐创作: 从零开始为游戏制作音乐&quot;">​</a></h1><ul><li><a href="https://www.bilibili.com/video/BV1uh4y1b7T9/?spm_id_from=333.337.search-card.all.click&amp;vd_source=9cdd98cc53d87aeb4190d2743832662b" target="_blank" rel="noreferrer">「磕作曲」ZUN号的力量！Jrpg战斗管弦配乐写法的固定套路是什么？</a></li></ul><h2 id="理论" tabindex="-1">理论 <a class="header-anchor" href="#理论" aria-label="Permalink to &quot;理论&quot;">​</a></h2><h3 id="游戏音乐应该怎么样" tabindex="-1">游戏音乐应该怎么样？ <a class="header-anchor" href="#游戏音乐应该怎么样" aria-label="Permalink to &quot;游戏音乐应该怎么样？&quot;">​</a></h3><ul><li>明确服务的游戏类型和场景</li><li>可无限循环</li><li>不会太长（30S-2.4Min）</li></ul><h3 id="一些思考过程" tabindex="-1">一些思考过程 <a class="header-anchor" href="#一些思考过程" aria-label="Permalink to &quot;一些思考过程&quot;">​</a></h3><ul><li>音乐创作的四个细分主轴 <img src="'+e+'" alt="alt text"><br> 场景：过场动画，游戏背景，游戏剧情事件</li><li>选择哪些乐器</li><li>限制乐器的数量和雕琢的时间。作为一个交付产品，和其他资产一样有交付节点。</li><li>聆听同类型游戏音乐</li></ul><h3 id="一些简单的创作方法" tabindex="-1">一些简单的创作方法 <a class="header-anchor" href="#一些简单的创作方法" aria-label="Permalink to &quot;一些简单的创作方法&quot;">​</a></h3><p><img src="'+o+'" alt="alt text"><br> 分层法很常见，几乎都用。但常常是一个基础上多种方式混合</p><h2 id="和弦" tabindex="-1">和弦 <a class="header-anchor" href="#和弦" aria-label="Permalink to &quot;和弦&quot;">​</a></h2><p>4736251 公式 五度圈 leading bass 顺接和弦公式</p><p>四个和弦循环 1645 根音 1451</p><h2 id="调" tabindex="-1">调 <a class="header-anchor" href="#调" aria-label="Permalink to &quot;调&quot;">​</a></h2><blockquote><p>“是调决定和弦，还是和弦呈现了调？”</p></blockquote><h3 id="_1️⃣-理论上-结构" tabindex="-1">1️⃣ 理论上（结构） <a class="header-anchor" href="#_1️⃣-理论上-结构" aria-label="Permalink to &quot;1️⃣ 理论上（结构）&quot;">​</a></h3><ul><li>调 → 限定了“默认和弦池”</li><li>比如 C大调 → 那7个和弦 👉 这是“生成关系”</li></ul><h3 id="_2️⃣-听感上-实际音乐" tabindex="-1">2️⃣ 听感上（实际音乐） <a class="header-anchor" href="#_2️⃣-听感上-实际音乐" aria-label="Permalink to &quot;2️⃣ 听感上（实际音乐）&quot;">​</a></h3><p>👉 是和弦在告诉你调</p><p>比如：</p><ul><li>C → F → G → C 你就听到 C大调</li></ul><p>✔️ 即使你没说“这是C调”</p><p>👉 所以更本质的说法是：</p><p><strong>调不是原因，而是总结</strong></p><p>—————————————————— 你这段思考其实已经很接近“真正的乐理核心”了，我帮你把几个关键点<strong>梳理成一条清晰主轴</strong>，避免被术语绕晕。</p><hr><h1 id="一、你说的-14个和弦-到底是什么关系" tabindex="-1">一、你说的“14个和弦”到底是什么关系？ <a class="header-anchor" href="#一、你说的-14个和弦-到底是什么关系" aria-label="Permalink to &quot;一、你说的“14个和弦”到底是什么关系？&quot;">​</a></h1><p>在一个调里（比如 <strong>C大调 / A小调</strong>），确实：</p><ul><li>7个音（C D E F G A B）</li><li>每个音叠三度 → 得到7个<strong>三和弦</strong></li><li>每个再加七度 → 得到7个<strong>七和弦</strong></li></ul><p>👉 所以你说的 <strong>14个和弦 = 调内和弦体系（diatonic harmony）</strong></p><h3 id="在-c-大调里就是" tabindex="-1">在 C 大调里就是： <a class="header-anchor" href="#在-c-大调里就是" aria-label="Permalink to &quot;在 C 大调里就是：&quot;">​</a></h3><p><strong>三和弦：</strong></p><ul><li>C（I）</li><li>Dm（ii）</li><li>Em（iii）</li><li>F（IV）</li><li>G（V）</li><li>Am（vi）</li><li>Bdim（vii°）</li></ul><p><strong>七和弦：</strong></p><ul><li>Cmaj7</li><li>Dm7</li><li>Em7</li><li>Fmaj7</li><li>G7</li><li>Am7</li><li>Bm7♭5</li></ul><p>✔️ 这不是“其中一种说法” 👉 而是：<strong>一个调的“基础素材库”</strong></p><hr><h1 id="二、那-1645、1451-是什么" tabindex="-1">二、那 1645、1451 是什么？ <a class="header-anchor" href="#二、那-1645、1451-是什么" aria-label="Permalink to &quot;二、那 1645、1451 是什么？&quot;">​</a></h1><p>👉 这是<strong>和弦进行（progression）</strong></p><ul><li>1645 = I → vi → IV → V</li><li>1451 = I → IV → V → I</li></ul><p>✔️ 它们不是“和弦种类” ✔️ 而是：<strong>从那14个和弦里选出来的“路径”</strong></p><p>👉 类比一下：</p><table tabindex="0"><thead><tr><th>概念</th><th>类比</th></tr></thead><tbody><tr><td>调（C大调）</td><td>一个语言</td></tr><tr><td>7个和弦</td><td>字词</td></tr><tr><td>1645</td><td>句子结构</td></tr></tbody></table><hr><h1 id="三、你问的关键-这些是-不同表述-吗" tabindex="-1">三、你问的关键：这些是“不同表述”吗？ <a class="header-anchor" href="#三、你问的关键-这些是-不同表述-吗" aria-label="Permalink to &quot;三、你问的关键：这些是“不同表述”吗？&quot;">​</a></h1><p>不是。</p><p>👉 它们是<strong>不同层级的概念</strong>：</p><h3 id="层级结构-非常重要" tabindex="-1">层级结构（非常重要） <a class="header-anchor" href="#层级结构-非常重要" aria-label="Permalink to &quot;层级结构（非常重要）&quot;">​</a></h3><p>1️⃣ <strong>调（Key）</strong></p><ul><li>决定音阶（C大调 = 白键体系）</li></ul><p>2️⃣ <strong>调内和弦（Diatonic chords）</strong></p><ul><li>从音阶生成的7个和弦（+扩展）</li></ul><p>3️⃣ <strong>和弦进行（Progression）</strong></p><ul><li>用这些和弦组成时间序列</li></ul><p>4️⃣ <strong>功能（Function）</strong></p><ul><li>T（主）/ S（下属）/ D（属）</li></ul><hr><p>👉 你困惑的根源是： <strong>把“素材”和“用法”混在了一起</strong></p><hr><h1 id="四、怎么判断-学究概念-vs-必要概念" tabindex="-1">四、怎么判断“学究概念 vs 必要概念”？ <a class="header-anchor" href="#四、怎么判断-学究概念-vs-必要概念" aria-label="Permalink to &quot;四、怎么判断“学究概念 vs 必要概念”？&quot;">​</a></h1><p>一个非常实用的判断标准：</p><h3 id="✔️-必学-创作核心" tabindex="-1">✔️ 必学（创作核心） <a class="header-anchor" href="#✔️-必学-创作核心" aria-label="Permalink to &quot;✔️ 必学（创作核心）&quot;">​</a></h3><ul><li>调（Key）</li><li>音阶（Scale）</li><li>和弦构成（Chord）</li><li>功能（T / S / D）</li><li>进行（Progression）</li></ul><p>👉 这些直接影响你写歌</p><hr><h3 id="⚠️-次要-偏学究-分析" tabindex="-1">⚠️ 次要（偏学究 / 分析） <a class="header-anchor" href="#⚠️-次要-偏学究-分析" aria-label="Permalink to &quot;⚠️ 次要（偏学究 / 分析）&quot;">​</a></h3><ul><li>调式名称（多利亚、利底亚等）</li><li>复杂命名（各种替代和弦命名法）</li><li>过细分类</li></ul><p>👉 不会这些也能写出好歌</p><h3 id="举例-c大调里" tabindex="-1">举例（C大调里）： <a class="header-anchor" href="#举例-c大调里" aria-label="Permalink to &quot;举例（C大调里）：&quot;">​</a></h3><p>正常：</p><ul><li>C – F – G</li></ul><p>借用：</p><ul><li>C – F – <strong>Fm</strong>（借用小调）</li></ul><p>👉 Fm 并不“错误” 👉 而是：<strong>制造情绪变化</strong></p><hr><h3 id="所以" tabindex="-1">所以： <a class="header-anchor" href="#所以" aria-label="Permalink to &quot;所以：&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>感觉</th></tr></thead><tbody><tr><td>调内和弦</td><td>稳定 / 自然</td></tr><tr><td>外来和弦</td><td>张力 / 色彩 / 转折</td></tr></tbody></table><hr><h1 id="七、调可以穷举吗" tabindex="-1">七、调可以穷举吗？ <a class="header-anchor" href="#七、调可以穷举吗" aria-label="Permalink to &quot;七、调可以穷举吗？&quot;">​</a></h1><p>👉 可以（理论上）</p><ul><li>12个音 → 12个大调</li><li>12个小调</li></ul><p>👉 一共 24 个常用调</p><hr><p>但：</p><p>👉 <strong>创作时不重要</strong></p><p>因为：</p><p>✔️ 1645 在任何调都是一样的结构 ✔️ 只是整体升降不同</p><hr><h1 id="八、你可以建立的-创作主轴-重点" tabindex="-1">八、你可以建立的“创作主轴”（重点） <a class="header-anchor" href="#八、你可以建立的-创作主轴-重点" aria-label="Permalink to &quot;八、你可以建立的“创作主轴”（重点）&quot;">​</a></h1><p>我给你一条非常实用的框架：</p><hr><h2 id="🎯-核心主轴-创作者版" tabindex="-1">🎯 核心主轴（创作者版） <a class="header-anchor" href="#🎯-核心主轴-创作者版" aria-label="Permalink to &quot;🎯 核心主轴（创作者版）&quot;">​</a></h2><h3 id="_1️⃣-调-音高环境" tabindex="-1">1️⃣ 调 = 音高环境 <a class="header-anchor" href="#_1️⃣-调-音高环境" aria-label="Permalink to &quot;1️⃣ 调 = 音高环境&quot;">​</a></h3><p>（选一个“世界”）</p><hr><h3 id="_2️⃣-和弦-情绪单位" tabindex="-1">2️⃣ 和弦 = 情绪单位 <a class="header-anchor" href="#_2️⃣-和弦-情绪单位" aria-label="Permalink to &quot;2️⃣ 和弦 = 情绪单位&quot;">​</a></h3><p>（稳定 / 紧张 / 回归）</p><ul><li>I → 稳定</li><li>V → 紧张</li><li>IV → 过渡</li></ul><hr><h3 id="_3️⃣-进行-情绪轨迹" tabindex="-1">3️⃣ 进行 = 情绪轨迹 <a class="header-anchor" href="#_3️⃣-进行-情绪轨迹" aria-label="Permalink to &quot;3️⃣ 进行 = 情绪轨迹&quot;">​</a></h3><p>（故事）</p><ul><li>1645 → 循环</li><li>1564 → 流行抒情</li><li>251 → 爵士感</li></ul><hr><h3 id="_4️⃣-非调内和弦-情绪调味" tabindex="-1">4️⃣ 非调内和弦 = 情绪调味 <a class="header-anchor" href="#_4️⃣-非调内和弦-情绪调味" aria-label="Permalink to &quot;4️⃣ 非调内和弦 = 情绪调味&quot;">​</a></h3><p>（关键高级点）</p><hr><p>👉 一句话总结：</p><p><strong>写歌不是在用“调”</strong> 👉 而是在用：</p><p>👉 <strong>“和弦如何移动”</strong></p><hr><h1 id="九、帮你校正一个非常关键的认知" tabindex="-1">九、帮你校正一个非常关键的认知 <a class="header-anchor" href="#九、帮你校正一个非常关键的认知" aria-label="Permalink to &quot;九、帮你校正一个非常关键的认知&quot;">​</a></h1><p>你说：</p><blockquote><p>“不能说调决定和弦，而是和弦呈现了调？”</p></blockquote><p>✔️ 我帮你升级成更准确版本：</p><p>👉 <strong>调 = 对一组和弦行为的总结标签</strong></p><hr><h1 id="最后一句-给创作者" tabindex="-1">最后一句（给创作者） <a class="header-anchor" href="#最后一句-给创作者" aria-label="Permalink to &quot;最后一句（给创作者）&quot;">​</a></h1><p>如果你只记一个核心：</p><p>👉 不要试图“理解所有概念”</p><p>而是：</p><p>👉 <strong>盯住这三件事：</strong></p><ol><li>哪些和弦可以用（调内）</li><li>它们之间怎么走（进行）</li><li>哪里可以打破（外来和弦）</li></ol><hr><p>如果你愿意，我可以帮你把 👉 “1645 / 1564 / 251 / 4536” 这些全部变成<strong>听感+情绪地图</strong>，会一下子通透很多。</p>',123)])])}const m=l(h,[["render",n]]);export{g as __pageData,m as default};
